function main(): void {
  const p: any = process;
  console.log(process.argv["0"] === process.argv[0], typeof process.argv["1"]);
  console.log(p.features.typescript, Array.isArray(p.moduleLoadList), p.moduleLoadList.length > 0, typeof p.moduleLoadList[0]);
  console.log(Array.isArray(p._events.newListener), Array.isArray(p._events.removeListener), p._events.newListener.length, typeof p._events.warning === "function" || typeof p._events.warning === "undefined");
  const fnNames = ["kill", "nextTick", "umask", "setuid", "getBuiltinModule", "binding", "assert", "ref", "unref", "threadCpuUsage", "setSourceMapsEnabled", "setUncaughtExceptionCaptureCallback", "initgroups"];
  console.log(fnNames.map((n) => n + ":" + p[n].length).join(" "));
  let called = 0;
  process.on("newListener", () => { called++; });
  process.on("exit", () => {});
  console.log(called);
}
